/**
 * @file webdav_push.h
 * @brief WebDAV Push Notification System for Linux/macOS Clients
 *
 * Implements real-time push notifications for WebDAV clients.
 * 
 * Supports:
 * - SSE (Server-Sent Events) for modern clients
 * - WebSocket for browser-based clients
 * - Long polling fallback for legacy clients
 * 
 * Clients can subscribe to:
 * - File/folder changes
 * - Project updates
 * - GUI updates
 * - System events
 *
 * Generated by Mistral Vibe.
 * Date: 2026-08-16
 */

#ifndef WEBDAV_PUSH_H
#define WEBDAV_PUSH_H

#include <stdint.h>
#include <stdbool.h>

// ============================================================================
// NOTIFICATION TYPES
// ============================================================================

/// @brief Types of WebDAV push notifications
typedef enum {
    WEBDAV_PUSH_FILE_CREATED = 0,     ///< New file created
    WEBDAV_PUSH_FILE_MODIFIED,       ///< File modified
    WEBDAV_PUSH_FILE_DELETED,        ///< File deleted
    WEBDAV_PUSH_FILE_MOVED,          ///< File moved/renamed
    WEBDAV_PUSH_FOLDER_CREATED,      ///< New folder created
    WEBDAV_PUSH_FOLDER_DELETED,       ///< Folder deleted
    WEBDAV_PUSH_PROJECT_UPDATED,      ///< Project file changed
    WEBDAV_PUSH_GUI_UPDATED,          ///< GUI definition changed
    WEBDAV_PUSH_SYSTEM_EVENT,         ///< System event (boot, shutdown, etc.)
    WEBDAV_PUSH_CUSTOM,               ///< Custom user-defined event
} WebDAVPushEventType;

// ============================================================================
// NOTIFICATION DATA
// ============================================================================

/// @brief Maximum path length for notifications
#define WEBDAV_PUSH_MAX_PATH 256

/// @brief Push notification data structure
/// @note Total size: ~300 bytes (fits in single packet)
typedef struct {
    WebDAVPushEventType type;           ///< Event type
    uint64_t timestamp;                 ///< Event timestamp (ms since boot)
    char path[WEBDAV_PUSH_MAX_PATH];    ///< File/folder path
    char old_path[WEBDAV_PUSH_MAX_PATH]; ///< Old path (for move/rename)
    uint32_t size;                      ///< File size (for create/modify)
    uint32_t client_id;                 ///< Client ID for targeted notifications
    char custom_data[64];              ///< Custom data (for custom events)
} WebDAVPushNotification;

// ============================================================================
// CLIENT MANAGEMENT
// ============================================================================

/// @brief Maximum number of connected push clients
#define WEBDAV_PUSH_MAX_CLIENTS 8

/// @brief Push client connection type
typedef enum {
    WEBDAV_PUSH_CLIENT_SSE = 0,        ///< Server-Sent Events
    WEBDAV_PUSH_CLIENT_WEBSOCKET,      ///< WebSocket
    WEBDAV_PUSH_CLIENT_LONG_POLL,     ///< Long polling
} WebDAVPushClientType;

/// @brief Push client information
typedef struct {
    bool active;                       ///< Connection active
    WebDAVPushClientType type;         ///< Connection type
    uint32_t client_id;                 ///< Unique client ID
    uint64_t connected_at;             ///< Connection timestamp
    uint64_t last_ping;                ///< Last ping/activity time
    char subscription[WEBDAV_PUSH_MAX_PATH]; ///< Subscribed path (empty = all)
} WebDAVPushClient;

// ============================================================================
// WATCH CONFIGURATION
// ============================================================================

/// @brief Maximum number of watched paths
#define WEBDAV_PUSH_MAX_WATCHED_PATHS 16

/// @brief Watched path configuration
typedef struct {
    bool enabled;                      ///< Watch enabled
    char path[WEBDAV_PUSH_MAX_PATH];   ///< Path to watch
    bool recursive;                    ///< Watch subdirectories
    WebDAVPushEventType event_mask;    ///< Which events to notify
} WebDAVPushWatchConfig;

/// @brief WebDAV push configuration
typedef struct {
    bool enabled;                              ///< Push notifications enabled
    uint16_t port;                            ///< Push notification port
    bool use_sse;                             ///< Enable SSE
    bool use_websocket;                      ///< Enable WebSocket
    bool use_long_poll;                      ///< Enable long polling
    WebDAVPushWatchConfig watches[WEBDAV_PUSH_MAX_WATCHED_PATHS];
    uint8_t watch_count;
} WebDAVPushConfig;

// ============================================================================
// INITIALIZATION
// ============================================================================

/**
 * @brief Initialize WebDAV push notification system
 *
 * @param config Configuration to use (NULL for defaults)
 * @return true on success
 */
bool webdav_push_init(const WebDAVPushConfig* config);

/**
 * @brief Shutdown WebDAV push notification system
 */
void webdav_push_shutdown(void);

/**
 * @brief Check if push notifications are enabled
 *
 * @return true if enabled
 */
bool webdav_push_is_enabled(void);

// ============================================================================
// CLIENT MANAGEMENT
// ============================================================================

/**
 * @brief Register a new push client
 *
 * @param type Client connection type
 * @param subscription Path to subscribe to ("" for all)
 * @return Client ID, or 0 on failure
 */
uint32_t webdav_push_client_register(WebDAVPushClientType type, const char* subscription);

/**
 * @brief Unregister a push client
 *
 * @param client_id Client ID to unregister
 * @return true on success
 */
bool webdav_push_client_unregister(uint32_t client_id);

/**
 * @brief Get client by ID
 *
 * @param client_id Client ID
 * @return Pointer to client, or NULL if not found
 */
WebDAVPushClient* webdav_push_client_get(uint32_t client_id);

/**
 * @brief Ping a client (keep connection alive)
 *
 * @param client_id Client ID
 */
void webdav_push_client_ping(uint32_t client_id);

/**
 * @brief Clean up disconnected clients
 */
void webdav_push_client_cleanup(void);

// ============================================================================
// EVENT HANDLING
// ============================================================================

/**
 * @brief Send a push notification
 *
 * @param notification Notification to send
 * @return true on success
 */
bool webdav_push_notify(const WebDAVPushNotification* notification);

/**
 * @brief Send notification to specific client
 *
 * @param client_id Target client ID
 * @param notification Notification to send
 * @return true on success
 */
bool webdav_push_notify_client(uint32_t client_id, const WebDAVPushNotification* notification);

/**
 * @brief Notify all clients about a file change
 *
 * @param path Changed file path
 * @param type Event type
 * @return true on success
 */
bool webdav_push_notify_file_change(const char* path, WebDAVPushEventType type);

/**
 * @brief Notify about project update
 *
 * @param project_path Project path
 * @return true on success
 */
bool webdav_push_notify_project_update(const char* project_path);

/**
 * @brief Notify about GUI update
 *
 * @param gui_path GUI path
 * @return true on success
 */
bool webdav_push_notify_gui_update(const char* gui_path);

// ============================================================================
// WATCH MANAGEMENT
// ============================================================================

/**
 * @brief Add a path to watch
 *
 * @param path Path to watch
 * @param recursive Watch subdirectories
 * @param event_mask Which events to notify
 * @return true on success
 */
bool webdav_push_watch_add(const char* path, bool recursive, WebDAVPushEventType event_mask);

/**
 * @brief Remove a watched path
 *
 * @param path Path to stop watching
 * @return true on success
 */
bool webdav_push_watch_remove(const char* path);

/**
 * @brief Check if a path is being watched
 *
 * @param path Path to check
 * @return true if watched
 */
bool webdav_push_watch_is_watched(const char* path);

/**
 * @brief Check file system for changes in watched paths
 *
 * Should be called periodically (e.g., in main loop)
 */
void webdav_push_check_changes(void);

// ============================================================================
// SSE ENDPOINTS
// ============================================================================

/**
 * @brief Handle SSE connection request
 *
 * @param client_id Client ID
 * @return SSE event stream (for HTTP response)
 */
const char* webdav_push_sse_stream(uint32_t client_id);

/**
 * @brief Send SSE event to client
 *
 * @param client_id Client ID
 * @param event_type Event type
 * @param data Event data JSON string
 */
void webdav_push_sse_send_event(uint32_t client_id, const char* event_type, const char* data);

// ============================================================================
// WEBSOCKET ENDPOINTS
// ============================================================================

/**
 * @brief Handle WebSocket connection
 *
 * @param client_id Client ID
 * @return true on success
 */
bool webdav_push_websocket_connect(uint32_t client_id);

/**
 * @brief Handle WebSocket disconnect
 *
 * @param client_id Client ID
 */
void webdav_push_websocket_disconnect(uint32_t client_id);

/**
 * @brief Send WebSocket message to client
 *
 * @param client_id Client ID
 * @param message Message to send
 */
void webdav_push_websocket_send(uint32_t client_id, const char* message);

// ============================================================================
// LONG POLLING ENDPOINTS
// ============================================================================

/**
 * @brief Handle long polling request
 *
 * @param client_id Client ID
 * @return JSON array of notifications, or empty if none
 */
const char* webdav_push_long_poll(uint32_t client_id);

/**
 * @brief Queue notification for long polling client
 *
 * @param client_id Client ID
 * @param notification Notification to queue
 */
void webdav_push_long_poll_queue(uint32_t client_id, const WebDAVPushNotification* notification);

#endif // WEBDAV_PUSH_H
